    """
    >>> flip_case('Hello')
    'hELLO'
    >>> flip_case('tEST')
    'Test'
    """
    flipped_string = ''
    for char in string:
        if char.isupper():
            flipped_string += char.lower()
        elif char.islower():
            flipped_string += char.upper()
        else:
            flipped_string += char
