def find_zero(xs: list):
    """
    Finds the zero point of a polynomial represented by its coefficients using Newton's method.
    Assumes xs has an even number of coefficients and the largest non-zero coefficient guarantees a solution.
    """
    # Initial guess
    guess = 0.0

    # Define the polynomial function
    def poly_function(x):
        return sum(coef * x ** exp for exp, coef in enumerate(xs))

    # Define the derivative of the polynomial function
    def poly_derivative(x):
        return sum(exp * coef * x ** (exp - 1) for exp, coef in enumerate(xs[1:], start=1))

    # Newton's method iteration
    while True:
        # Calculate the next guess using Newton's method
        next_guess = guess - poly_function(guess) / poly_derivative(guess)

        # Check if the absolute value of the function value at the guess is close to zero
        if abs(poly_function(next_guess)) < 1e-9:
            return next_guess

        # Update the guess for the next iteration
        guess = next_guess

