def generate_fibonacci(n):
    """
    Generate the nth Fibonacci number.
    """
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        fib = [0, 1]
        for i in range(2, n + 1):
            fib.append(fib[i - 1] + fib[i - 2])
        return fib[n]

def prime_fib(n):
    """
    Return the nth number that is a Fibonacci number and prime.
