def modp(n: int, p: int):
    """
    Return 2^n modulo p (be aware of numerics).
    """
    if p == 1:
        return 0
    if n == 0:
        return 1
    result = 1
    base = 2 % p
    while n > 0:
        if n % 2 == 1:
            result = (result * base) % p
        base = (base * base) % p
        n //= 2
    return result

