def fib(n: int):
    """
    Return n-th Fibonacci number.
    """
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        prev = 0
        current = 1
        for _ in range(2, n + 1):
            temp = current
            current += prev
            prev = temp
        return current

