def get_row(lst, x):
    """
    Returns a list of tuples containing the coordinates of integer x in the input list.

    Coordinates are sorted by rows in ascending order and within each row, by columns in descending order.

    Args:
    lst (list): A 2-dimensional list.
    x (int): The integer to search for.

    Returns:
    list: A list of tuples representing the coordinates of integer x.
    """

    coordinates = []

    for row_index, row in enumerate(lst):
        for col_index, val in sorted(enumerate(row), key=lambda x: x[1], reverse=True):
            if val == x:
                coordinates.append((row_index, col_index))

