def histogram(test):
    """
    Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.
    """
    if not test:
        return {}

    # Split the string into individual letters
    letters = test.split()

    # Count occurrences of each letter
    letter_count = {}
    for letter in letters:
        if letter in letter_count:
            letter_count[letter] += 1
        else:
            letter_count[letter] = 1

    # Find the maximum count
    max_count = max(letter_count.values())

    # Find letters with the maximum count
    max_letters = {letter: count for letter, count in letter_count.items() if count == max_count}

    return max_letters

def select_words(s, n):
    """
    Given a string s and a natural number n, return a list of all words from string s 
    that contain exactly n consonants, in the order these words appear in the string s.
    If the string s is empty then return an empty list.
    """
    if not s:
        return []

    def count_consonants(word):
        consonants = set("bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ")
        return sum(1 for letter in word if letter in consonants)

    words = s.split()
    result = []
    for word in words:
        if count_consonants(word) == n:
            result.append(word)
    return result

