def get_odd_collatz(n):
    """
    Returns a sorted list of odd numbers in the Collatz sequence starting from n.
    """
    collatz_sequence = [n]
    while n != 1:
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1
        collatz_sequence.append(n)
    odd_numbers = [num for num in collatz_sequence if num % 2 != 0 and num != 1]
    return sorted(odd_numbers)

def valid_date(date):
    """
    Validate a given date string and return True if valid, otherwise False.
    The date is valid if it satisfies the following rules:
    1. The date string is not empty.
    2. The number of days is within the valid range for the corresponding month.
    3. The month is between 1 and 12.
    4. The date is in the format: mm-dd-yyyy.
    """
    if not date:
        return False

    parts = date.split('-')
    if len(parts) != 3:
        return False

    month, day, year = parts
    if not month.isdigit() or not day.isdigit() or not year.isdigit():
        return False

    month = int(month)
    day = int(day)
    year = int(year)

    if month < 1 or month > 12:
        return False

    if month in [1, 3, 5, 7, 8, 10, 12]:
        if day < 1 or day > 31:
            return False
    elif month in [4, 6, 9, 11]:
        if day < 1 or day > 30:
            return False
    elif month == 2:
        if day < 1 or day > 29:
            return False

    return True

