def tri(n):
    """
    Return the first n + 1 numbers of the Tribonacci sequence.
    """
    def calculate_tribonacci(num):
        if num == 0:
            return 3
        elif num == 1:
            return 2
        elif num == 2:
            return 2
        else:
            return calculate_tribonacci(num - 1) + calculate_tribonacci(num - 2) + calculate_tribonacci(num - 3)

    sequence = []
    for i in range(n + 1):
        sequence.append(calculate_tribonacci(i))

    return sequence

