            if smallest_positive_integer is None or num < smallest_positive_integer:
                smallest_positive_integer = num

    return (largest_negative_integer, smallest_positive_integer)

def is_equal_to_sum_even(n):
    """Evaluate whether the given number n can be written as the sum of exactly 4 positive even numbers"""

    # Check if n is even
    if n % 2 != 0:
        return False

    # Generate all combinations of 4 positive even numbers
    for i in range(1, n//2 + 1):
        for j in range(i + 1, n//2 + 1):
            for k in range(j + 1, n//2 + 1):
                for l in range(k + 1, n//2 + 1):
                    if i + j + k + l == n:
                        return True
    return False

