def file_name_check(file_name):
    digits_count = sum([char.isdigit() for char in file_name])
    if digits_count > 3:
        return 'No'

    dots_count = file_name.count('.')
    if dots_count != 1:
        return 'No'

    file_name_parts = file_name.split('.')
    prefix = file_name_parts[0]
    if not prefix or not prefix[0].isalpha():
        return 'No'

    suffix = file_name_parts[1]
    if suffix not in ['txt', 'exe', 'dll']:
        return 'No'

    return 'Yes'

from math import sqrt


def is_prime(n):
    """
    Check if a number is prime.
    """
    if n <= 1:  # Numbers less than or equal to 1 are not prime
        return False

    for i in range(2, int(sqrt(n)) + 1):
        if n % i == 0:
            return False

    return True


def words_in_sentence(sentence):
    """
    Extract the words from the sentence whose lengths are prime numbers.
    """
    words = sentence.split()
    prime_words = []

    for word in words:
        if is_prime(len(word)):
            prime_words.append(word)

    return " ".join(prime_words)

def order_by_points(nums):
    digit_sums = []
    for num in nums:
        if num < 0:
            num_str = str(num)[1:]  # remove the negative sign
        else:
            num_str = str(num)
        digit_sum = sum(int(digit) for digit in num_str)
        digit_sums.append(digit_sum)

    sorted_nums = [num for _, num in sorted(zip(digit_sums, nums))]
    return sorted_nums

def specialFilter(nums):
    count = 0
    for num in nums:
        if num > 10:
            num_str = str(num)
            first_digit = int(num_str[0])
            last_digit = int(num_str[-1])
            if first_digit % 2 == 1 and last_digit % 2 == 1:
                count += 1
    return count

def get_max_triples(n):
    count = 0
    for i in range(1, n-1):
        for j in range(i+1, n):
            for k in range(j+1, n+1):
                if (i * i - i + 1 + j * j - j + 1 + k * k - k + 1) % 3 == 0:
                    count += 1
    return count

def bf(planet1, planet2):
    planet_order = ['Mercury', 'Venus', 'Earth', 'Mars', 'Jupiter', 'Saturn', 'Uranus', 'Neptune']

    if planet1 not in planet_order or planet2 not in planet_order:
        return ()

    start_index = planet_order.index(planet1)
    end_index = planet_order.index(planet2)

    if start_index < end_index:
        between = planet_order[start_index+1:end_index]
    else:
        between = planet_order[end_index+1:start_index]

    return tuple(sorted(between, key=lambda x: planet_order.index(x)))

def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

def x_or_y(n, x, y):
    """
    Return the value of x if n is a prime number, or y otherwise.
    """
    if is_prime(n):
        return x
    else:
        return y

