def compare(game,guess):
    """
    Determine if a person correctly guessed the results of a number of matches.
    Return an array denoting how far off each guess was.
    """
    results = []
    for i in range(len(game)):
        if game[i] == guess[i]:
            results.append(0)
        else:
            results.append(abs(game[i] - guess[i]))
    return results

def find_max(words):
    max_chars = 0
    max_word = ""

    for word in words:
        unique_chars = len(set(word))

        if unique_chars > max_chars:
            max_chars = unique_chars
            max_word = word
        elif unique_chars == max_chars:
            if word < max_word:
                max_word = word

    return max_word

import hashlib

def string_to_md5(text):
    """
    Given a string 'text', return its md5 hash equivalent string.
    If 'text' is an empty string, return None.

    >>> string_to_md5('Hello world') == '3e25960a79dbc69b674cd4ec67a72c62'
    """
    if not text:
        return None
    return hashlib.md5(text.encode()).hexdigest()
